control='''test("initial history readiness rejects absent and hidden rows and recovers", async ({ page }) => {
  await page.setContent('<div role="log"></div>');
  await page.evaluate(() => {
    const observers = new Set<MutationObserver>();
    const frames = new Set<number>();
    const NativeObserver = window.MutationObserver;
    const request = window.requestAnimationFrame.bind(window);
    const cancel = window.cancelAnimationFrame.bind(window);
    window.MutationObserver = class extends NativeObserver {
      override observe(target: Node, options?: MutationObserverInit) {
        super.observe(target, options); observers.add(this);
      }
      override disconnect() { super.disconnect(); observers.delete(this); }
    };
    window.requestAnimationFrame = callback => {
      const id = request(time => { frames.delete(id); callback(time); });
      frames.add(id); return id;
    };
    window.cancelAnimationFrame = id => { frames.delete(id); cancel(id); };
    (window as unknown as Record<string, unknown>).__historyReadiness = { observers, frames };
  });
  const target = { id: "history-119", text: "History row 119" };
  const pending = () => page.evaluate(() => {
    const state = (window as unknown as { __historyReadiness: { observers: Set<MutationObserver>; frames: Set<number> } }).__historyReadiness;
    return { observers: state.observers.size, frames: state.frames.size };
  });
  await expect(page.evaluate(waitForInitialHistory, target)).rejects.toThrow("Initial history readiness exceeded 5000ms: history-119");
  expect(await pending()).toEqual({ observers: 0, frames: 0 });
  await page.evaluate(() => {
    document.querySelector('[role="log"]')!.innerHTML = '<div data-message-id="history-119" hidden><span>History row 119</span></div>';
  });
  await expect(page.evaluate(waitForInitialHistory, target)).rejects.toThrow("Initial history readiness exceeded 5000ms: history-119");
  expect(await pending()).toEqual({ observers: 0, frames: 0 });
  await page.evaluate(() => { document.querySelector<HTMLElement>('[data-message-id="history-119"]')!.hidden = false; });
  await page.evaluate(waitForInitialHistory, target);
  expect(await pending()).toEqual({ observers: 0, frames: 0 });
});

